    const rotationZ = gsap.utils.random(-50, 50);
    const setZ = gsap.quickSetter(item, 'z', 'px');

    gsap.fromTo(
      item,
      {
        rotationX,
        rotationY,
        rotationZ,
      },
      {
        rotationX: -rotationX,
        rotationY: -rotationY,
        rotationZ: -rotationZ,
        ease: 'none',
        scrollTrigger: {
          trigger: item,
          start: 'top bottom+=20%',
          end: 'bottom top-=20%',
          scrub: true,
          invalidateOnRefresh: true,
          onUpdate(self) {
            const z = Math.pow(Math.sin(self.progress * Math.PI), 4) * -300;
            setZ(z);
          },
        },
      }
    );
  }

